typedef enum { ROCK, PAPER, SCISSORS } Move;

/*
* wins[] is defined in moves.c. "extern" tells other .c files that include
* this header that it exists, so main.c can use it too.
*
*   wins[0] counts ties, wins[1] counts player 1's wins, wins[2] counts player 2's wins
*/
extern int wins[3];

const char *name_of_move(Move move);
Move random_move(void);
int winner(Move a, Move b);
void print_tally(void);
